#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill. Owner-run setup for #637: deploys infra/openmeteo-worker
# and sets OPENMETEO_PROXY_URL + OPENMETEO_PROXY_TOKEN (.env + GitHub secrets).
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6

# Run from anywhere: work in this checkout (gh secret set targets its repo),
# but keep local secrets in the main checkout's .env, which config.py loads.
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
MAIN_ROOT="$(dirname "$(git rev-parse --path-format=absolute --git-common-dir)")"
ENV_FILE="$MAIN_ROOT/.env"
PY="$REPO_ROOT/.venv/bin/python"
[[ -x "$PY" ]] || PY="python3"
WORKER_DIR="$REPO_ROOT/infra/openmeteo-worker"
WORKER_NAME="mirror-market-openmeteo"
# Pinned, not @latest: 4.160.0 was released 2026-11-10.
WRANGLER=(npx --yes wrangler@4.160.0)
# One pin, the same request shape Layer 5 sends (3 variables, 30 + 7 days):
# 1 weighted Open-Meteo call per test request.
TEST_QUERY="latitude=42.0&longitude=-93.5&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&past_days=30&forecast_days=7&timezone=auto"

for tool in node npx curl openssl gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed; install it and re-run."; exit 1; }
done

banner "Open-Meteo Worker · Layer 5's own weather quota (#637)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare account and workers.dev subdomain"
say "Open-Meteo's free quota is shared by everyone on a GitHub runner's IP."
say "A Cloudflare Worker gets its own quota. Workers Free is \$0: 100,000"
say "requests/day; we send about 2."
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "Log in (you already have an account from the R2 setup), or sign up free."
step "If Cloudflare asks you to choose a workers.dev subdomain, choose one."
step "Pick any name. The Worker will live at"
step "  https://$WORKER_NAME.<your-subdomain>.workers.dev"
note "Cloudflare's labels move. The page is 'Workers & Pages' (under Compute) in the sidebar."
pause "Press Enter once the Workers & Pages page is open."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Log wrangler in"
say "wrangler is Cloudflare's command-line tool, and npx fetches it for you."
say "It opens your browser and asks you to allow access to your account."
# `whoami --json` exits non-zero when not authenticated (wrangler docs).
if (cd "$WORKER_DIR" && "${WRANGLER[@]}" whoami --json >/dev/null 2>&1); then
  note "wrangler is already logged in:"
  (cd "$WORKER_DIR" && "${WRANGLER[@]}" whoami 2>/dev/null | grep -iE "logged in|account" | head -n 4) || true
else
  pause "Press Enter to run 'wrangler login'. Click Allow in the browser."
  (cd "$WORKER_DIR" && "${WRANGLER[@]}" login)
  (cd "$WORKER_DIR" && "${WRANGLER[@]}" whoami --json >/dev/null 2>&1) \
    || { warn "wrangler still isn't logged in. Re-run this wizard."; exit 1; }
fi
pause "Press Enter to continue."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Deploy the Worker"
say "This uploads infra/openmeteo-worker/src/worker.js, about 90 lines. It only"
say "forwards GET /v1/forecast, and only with the secret header from the next"
say "stage. Until that secret exists, it refuses every request."
WORKER_URL=""
if confirm "Deploy '$WORKER_NAME' with wrangler now? (No = paste it in the dashboard)"; then
  DEPLOY_LOG=$(mktemp)
  (cd "$WORKER_DIR" && "${WRANGLER[@]}" deploy) 2>&1 | tee "$DEPLOY_LOG"
  WORKER_URL=$(grep -Eo "https://$WORKER_NAME\.[a-z0-9-]+\.workers\.dev" "$DEPLOY_LOG" | head -n 1 || true)
  rm -f "$DEPLOY_LOG"
  DEPLOYED_BY=wrangler
else
  DEPLOYED_BY=dashboard
  open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages/create"
  step "Choose to start from 'Hello World', name it $WORKER_NAME, and click Deploy."
  step "Click 'Edit code'. Replace all of it with infra/openmeteo-worker/src/worker.js,"
  step "which is now on your clipboard. Then click Deploy."
  if command -v pbcopy >/dev/null 2>&1; then pbcopy < "$WORKER_DIR/src/worker.js"; else note "(no pbcopy, so copy the file by hand)"; fi
  step "Under Settings, set the compatibility date to 2025-11-01 or later."
  step "The cache option needs 2024-11-11 or later."
  pause "Press Enter once it's deployed."
fi
if [[ -n "$WORKER_URL" ]]; then
  OPENMETEO_PROXY_URL="$WORKER_URL"
  printf '  %s✓%s Worker URL (from wrangler): %s\n' "$GREEN" "$RESET" "$OPENMETEO_PROXY_URL"
else
  ask OPENMETEO_PROXY_URL "Paste the Worker's URL (https://$WORKER_NAME.<subdomain>.workers.dev):"
fi
OPENMETEO_PROXY_URL="${OPENMETEO_PROXY_URL%/}"
while [[ ! "$OPENMETEO_PROXY_URL" =~ ^https://[A-Za-z0-9.-]+$ ]]; do
  warn "Use an https:// URL with no path. Example: https://$WORKER_NAME.example.workers.dev"
  ask OPENMETEO_PROXY_URL "Worker URL:"
  OPENMETEO_PROXY_URL="${OPENMETEO_PROXY_URL%/}"
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Generate the shared secret and give it to the Worker"
say "This makes a random 64-character token. The Worker gets it as PROXY_TOKEN."
say "GitHub gets it as OPENMETEO_PROXY_TOKEN. It is never printed."
OPENMETEO_PROXY_TOKEN="$(_existing OPENMETEO_PROXY_TOKEN || true)"
if [[ -n "$OPENMETEO_PROXY_TOKEN" ]] && ! confirm "A token already exists in $ENV_FILE. Make a new one (rotate)?"; then
  note "Keeping the existing token."
else
  OPENMETEO_PROXY_TOKEN="$(openssl rand -hex 32)"
  note "Generated a new token."
fi
if [[ "$DEPLOYED_BY" == wrangler ]]; then
  # Piped on stdin, so the value never appears in argv or the terminal.
  printf '%s' "$OPENMETEO_PROXY_TOKEN" | (cd "$WORKER_DIR" && "${WRANGLER[@]}" secret put PROXY_TOKEN) >/dev/null \
    || { warn "wrangler secret put failed. Re-run this wizard."; exit 1; }
  printf '  %s✓ set%s Worker secret PROXY_TOKEN\n' "$GREEN" "$RESET"
else
  if command -v pbcopy >/dev/null 2>&1; then
    printf '%s' "$OPENMETEO_PROXY_TOKEN" | pbcopy
    note "The token is on your clipboard and not shown here."
  else
    warn "No pbcopy, so set the secret with wrangler from $WORKER_DIR:"
    warn "  npx wrangler secret put PROXY_TOKEN   (paste it from $ENV_FILE)"
  fi
  step "In the Worker, go to Settings → Variables and Secrets → Add."
  step "Type: Secret. Name: PROXY_TOKEN. Paste the value and click Deploy."
  pause "Press Enter once PROXY_TOKEN is saved."
fi
write_env OPENMETEO_PROXY_TOKEN "$OPENMETEO_PROXY_TOKEN"
write_env OPENMETEO_PROXY_URL "$OPENMETEO_PROXY_URL"
if command -v pbcopy >/dev/null 2>&1; then printf '' | pbcopy; fi
pause "Press Enter to test it."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "End-to-end test"
HDRS=$(mktemp); BODY=$(mktemp)
trap 'rm -f "$HDRS" "$BODY"' EXIT
# The header comes from a file descriptor, so the token stays out of argv.
_proxy_get() {
  curl -sS -o "$BODY" -D "$HDRS" -w '%{http_code}' --max-time 40 \
    -H @<(printf 'X-Proxy-Token: %s\n' "$1") "$OPENMETEO_PROXY_URL/v1/forecast?$TEST_QUERY" || true
}
say "1) No token. The Worker must refuse it (401)."
code=$(curl -sS -o /dev/null -w '%{http_code}' --max-time 40 "$OPENMETEO_PROXY_URL/v1/forecast?$TEST_QUERY" || true)
if [[ "$code" == 401 ]]; then printf '  %s✓%s refused: HTTP 401\n' "$GREEN" "$RESET"
else warn "expected 401 and got HTTP $code. Is the URL right? Is the secret saved?"; fi
say "2) With the token. The Worker must forward to Open-Meteo (200)."
ok=0
for attempt in 1 2 3 4 5 6; do
  code=$(_proxy_get "$OPENMETEO_PROXY_TOKEN")
  [[ "$code" == 200 ]] && { ok=1; break; }
  # A new secret takes a few seconds to reach every Cloudflare location.
  note "attempt $attempt: HTTP $code $(grep -i '^x-mirror-proxy-error' "$HDRS" | tr -d '\r' || true). Retrying in 10 s"
  sleep 10
done
if (( ok )); then
  printf '  %s✓%s forwarded: HTTP 200, %s bytes\n' "$GREEN" "$RESET" "$(wc -c < "$BODY" | tr -d ' ')"
  grep -iE '^x-ratelimit-(cost|remaining|window)' "$HDRS" | tr -d '\r' | sed 's/^/    /' || true
  say ""
  say "Read X-RateLimit-Remaining above. The Worker's quota is new, so it should"
  say "be close to 10,000 (minus today's calls through this Worker). If it is far"
  say "lower, the quota is shared after all. That happens if Open-Meteo groups"
  say "all workers.dev Workers together, which no primary source rules out."
  say "If so, add a custom domain you own to the Worker. See the README."
else
  warn "The Worker never answered 200. Fix it, then re-run (values already saved are kept)."
  SKIPPED+=("end-to-end test (last HTTP $code)")
fi
say "3) The Layer 5 fetcher itself, through the Worker (24 calls of quota)."
if (( ok )) && confirm "Run fetchers.weather.fetch_all_regions() through the Worker now?"; then
  if ! OPENMETEO_PROXY_URL="$OPENMETEO_PROXY_URL" OPENMETEO_PROXY_TOKEN="$OPENMETEO_PROXY_TOKEN" "$PY" - <<'PYEOF'
import logging
logging.basicConfig(level=logging.INFO, format="    %(message)s")
from fetchers.weather import fetch_all_regions
frames = fetch_all_regions()
filled = sum(1 for df in frames.values() if not df.empty)
print(f"    {filled}/{len(frames)} pins answered")
raise SystemExit(0 if filled == len(frames) else 1)
PYEOF
  then
    SKIPPED+=("fetcher run through the Worker failed; see the output above")
  fi
fi
pause "Press Enter to save the GitHub secrets."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub secrets"
say "The daily deploy and the dispatched refresh read both secrets"
say "(.github/workflows/deploy-dashboard.yml, refresh-prices.yml)."
say "Set them together. If only one is set, Layer 5 fails on purpose."
if confirm "Set OPENMETEO_PROXY_URL and OPENMETEO_PROXY_TOKEN on $(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || echo this repo)?"; then
  set_secret OPENMETEO_PROXY_URL "$OPENMETEO_PROXY_URL"
  set_secret OPENMETEO_PROXY_TOKEN "$OPENMETEO_PROXY_TOKEN"
else
  SKIPPED+=("GitHub secrets OPENMETEO_PROXY_URL + OPENMETEO_PROXY_TOKEN (values are in $ENV_FILE)")
fi
say ""
say "Check: after the next daily deploy, its log should say 'via Worker':"
note "  gh run view <run-id> --log | grep 'Requesting weather'"
note "  $PY main.py --doctor    # both now read 'set'"
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
